#!/bin/bash
# usage: wrap.sh <generated Wasm.lean> <out>  -- module wrapper (see NOTICES/SpecTec)
set -euo pipefail
{
cat <<'HDR'
module

/-!
# Wasm 3.0 as SpecTec's Lean 4 backend renders it (generated; do not edit)

Generated by the Lean 4 backend of `Wasm-DSL/spectec` (branch `lean4-wip`, ported onto
`rocq-backend`, with local patches) from `WebAssembly/spec@608711107b7f1edb13efd57b7d79b49477462d36`
`specification/wasm-3.0/[012345]*.spectec` (three alias edits). Provenance, commands and the
list of patches: `NOTICES/spectec/README.md`, `docs/projects/wasm-extras.md`.

The only edits after generation are this header, the namespace, `autoImplicit`, and making the
preamble's `Append (Option _)` instance and `opaqueDef` macro scoped.
-/

@[expose] public section

set_option autoImplicit true

namespace SpecTecLean

HDR
sed -e 's/^instance : Append (Option a) where$/scoped instance : Append (Option a) where/' \
    -e 's/^macro "opaqueDef" : term =>/scoped macro "opaqueDef" : term =>/' "$1"
printf '\nend SpecTecLean\n'
} > "$2"
